    completion_dir = "invoke/completion/"
    for name in names:
        completion_file = os.path.join(completion_dir, f"{name}.completion")
        if os.path.exists(completion_file):
            with open(completion_file, 'r') as file:
                print(file.read())
            return
    raise FileNotFoundError(f"No completion script found for shell: {shell}")

def print_completion_script(shell: str, names: List[str]) -> None:
    """Implement the `print_completion_script` function (parameters: shell, names)."""
    completion_dir = "invoke/completion/"
    completion_files = [f for f in os.listdir(completion_dir) if f.startswith('.')]
    completion_content = ""
    for name in names:
        for completion_file in completion_files:
            if completion_file.startswith(f".{name}_"):
                with open(os.path.join(completion_dir, completion_file), 'r') as file:
                    completion_content += file.read()
    if shell == "bash":
        print(completion_content)
    elif shell == "zsh":
        print(completion_content.replace('complete -W', 'compdef _invoke'))
    else:
        raise ValueError("Unsupported shell")

